/* activerooms-20261029e (Dan, Oct 29 2026): e3 (fix: wide-mode duplicate-box loop; column 58%) e2 = title styled like the .box header (HUB ROOMS: 9.5px, weight 500, letter-spacing .3px, uppercase); list floats in a reserved right column (48%) when the hint area is >=360px wide, else full-width block below the hint; timer m:ss / h:mm:ss from the owner bot meter (GET /api/account/botmeter/status?id=<live.meter>: startedAt, serverNow, elapsedSec, state), Paused badge only when meter state is paused_* or a paused:true field arrives. e = list is a normal full-width block placed right AFTER the .hrhint block (no absolute overlay, and outside the hint so its .65 opacity no longer dims it); font-size/family/line-height copied at draw time from the live .hrhint computed style; full white with button-like text shadow. d = no Re-enter button, the room name is the clickable re-enter control; all text inherits the .hrhint size (9px in the final .hrw rules) so it matches 'Pick a room type' / My rooms; wide name box, members ellipsize first; badge slot only if r.badge exists. c = Hub Rooms look (inherits .hrw font, .hrr row, .hrbtns button), one line per room: name - people [Re-enter]; name = topic, else room type label, else short id; full id in tooltip. b: "Active rooms" list on the right of the Hub Rooms start list. Shows live pre-rooms / bot rooms the viewer is a member of (GET /api/prerooms/mine, status live) with a Re-enter button. Roll back: remove the script tag in index.html. */
(function(){var D=document,rooms=[],last=0;
function css(){if(D.getElementById('arCss'))return;var s=D.createElement('style');s.id='arCss';s.textContent='.arBox.arWide{float:right;width:58%;margin:0 0 4px 8px}.arBox .arH{font-size:9.5px!important;font-weight:500!important;letter-spacing:.3px;text-transform:uppercase;color:#fff;margin:0 0 4px}.arBox .arTime{flex:none;font:inherit;font-variant-numeric:tabular-nums;color:#fff}.arBox .arPause{flex:none;font:inherit;padding:0 5px;border-radius:7px;background:rgba(160,160,160,.35);border:1px solid rgba(200,200,200,.5);color:#eee}.arBox{position:relative;z-index:5;clear:both;pointer-events:auto;display:block;width:100%;box-sizing:border-box;margin:6px 0 4px;padding:0 2px;color:#fff;opacity:1;text-shadow:0 1px 2px rgba(0,0,0,.65)}.arBox .arH{display:block;font:inherit;margin:0 0 3px}.arBox .arRow{display:flex;align-items:center;gap:5px;width:100%;box-sizing:border-box;font:inherit;color:#fff;background:rgba(0,0,0,.28);border:1px solid rgba(255,255,255,.18);border-radius:6px;padding:3px 6px;margin:0 0 3px;white-space:nowrap;overflow:hidden}.arBox .arRow:hover{background:rgba(var(--hub-blue-rgb),.18);border-color:rgba(var(--hub-blue-rgb),.5)}.arBox .arName{flex:0 1 auto;min-width:min(9em,45%);font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:inherit;color:#fff;cursor:pointer;text-decoration:underline;text-decoration-color:rgba(255,255,255,.35);text-underline-offset:2px;border-radius:3px;outline:none}.arBox .arName:hover,.arBox .arName:focus-visible{text-decoration-color:#fff;background:rgba(var(--hub-blue-rgb),.35)}.arBox .arMem{flex:1 1 0;min-width:3em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:inherit;color:rgba(255,255,255,.92)}.arBox .arBadge{flex:none;font:inherit;padding:0 5px;border-radius:7px;border:1px solid rgba(255,255,255,.25)}.arBox .arNone{font:inherit}';D.head.appendChild(s);}
function load(){if(Date.now()-last<10000)return;last=Date.now();fetch('/api/prerooms/mine',{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(j){if(!j)return;var L=(j.rooms||[]).filter(function(x){return x.status==='live';});Promise.all(L.map(function(x){return fetch('/api/prerooms/'+encodeURIComponent(x.id),{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(v){v=v&&(v.view||v.room||v);var p=(v&&v.live&&v.live.people)||(v&&v.roster)||[];var seen={};x.names=p.map(function(q){return q.name;}).filter(function(n){if(!n||seen[n])return false;seen[n]=1;return true;});x.live=v&&v.live?v.live.room:'';x.meter=v&&v.live?v.live.meter:'';x.paused=!!(v&&(v.paused||(v.live&&v.live.paused)));var c=v&&v.center;if(c&&c.topic)x.topic=c.topic;}).catch(function(){x.names=[];});})).then(function(){rooms=L;draw(true);L.forEach(function(x){if(!x.meter)return;fetch('/api/account/botmeter/status?id='+encodeURIComponent(x.meter),{credentials:'same-origin',cache:'no-store'}).then(function(r){return r.ok?r.json():null;}).then(function(m){if(!m||m.state==='ended')return;var st=Date.parse(m.startedAt);if(isNaN(st))return;x.t0=Date.now()-((m.serverNow||Date.now())-st);x.paused=x.paused||/^paused/.test(m.state||'');tick();}).catch(function(){});});});}).catch(function(){});}
function fmt(ms){var t=Math.max(0,Math.floor(ms/1000)),h=Math.floor(t/3600),m=Math.floor(t%3600/60),x=t%60;var p=function(n){return(n<10?'0':'')+n;};return h?h+':'+p(m)+':'+p(x):m+':'+p(x);}var tk=0;function tick(){draw(true);if(!tk)tk=setInterval(function(){D.querySelectorAll('.arBox .arTime').forEach(function(e){e.textContent=fmt(Date.now()-(+e.dataset.t0));});},1000);}function fw(){var f=D.getElementById('prFrame');return f&&f.contentWindow;}
function reenter(id){var bt=[].filter.call(D.querySelectorAll('.hrw .hrnewcol button.hrnew'),function(b){return /^Bot rooms?$/i.test(b.textContent.trim());})[0];
 if(!(window.__prActive&&fw()))if(bt)bt.click();var n=0,opened=false,t=setInterval(function(){n++;var w=fw();if(n>60){clearInterval(t);return;}
 try{if(!w||!w.prCards)return;var c=w.prCards.current&&w.prCards.current();if(!c||c.id!==id){if(!opened){opened=true;w.prCards.open(id);}return;}
 if(c.live&&w.prCards.enterLive()){clearInterval(t);}}catch(e){}},250);}
function draw(force){D.querySelectorAll('.hrw .hrnewcol').forEach(function(col){var host=col.parentElement;if(!host)return;var box=[host.nextElementSibling,host.previousElementSibling].filter(function(e){return e&&e.classList.contains('arBox');})[0]||null;
 if(box&&!force)return;if(!box){css();box=D.createElement('div');box.className='arBox';host.parentNode.insertBefore(box,host.nextSibling);load();}
 var wide=false;/* roomjump-20261029: always below, never floats up beside the buttons */if(wide!==box.classList.contains('arWide')||!box.dataset.p){box.dataset.p=1;box.classList.toggle('arWide',wide);host.parentNode.insertBefore(box,wide?host:host.nextSibling);}try{var cs=getComputedStyle(host);box.style.fontFamily=cs.fontFamily;box.style.fontSize=cs.fontSize;box.style.lineHeight=cs.lineHeight;}catch(e){}box.innerHTML='';var h=D.createElement('div');h.className='arH';h.textContent='Active rooms';box.appendChild(h);
 if(!rooms.length){var e=D.createElement('div');e.className='arNone';e.textContent='No live rooms';box.appendChild(e);}
 rooms.forEach(function(r){var row=D.createElement('div');row.className='arRow';var full=r.live||r.id;row.title=full+(r.live&&r.id?' ('+r.id+')':'');var nm=(r.topic||r.type||'').trim()||String(full).slice(0,11);var n=D.createElement('span');n.className='arName';n.textContent=nm;n.setAttribute('role','button');n.tabIndex=0;n.setAttribute('aria-label','Re-enter '+nm);var go=function(e){e.preventDefault();e.stopPropagation();reenter(r.id);};n.addEventListener('click',go);n.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '||e.key==='Spacebar')go(e);});row.appendChild(n);if(r.names&&r.names.length){var m=D.createElement('span');m.className='arMem';m.textContent=r.names.join(', ');m.title=r.names.join(', ');row.appendChild(m);}if(r.t0){var tm=D.createElement('span');tm.className='arTime';tm.title='Time open since go-live';tm.dataset.t0=r.t0;tm.textContent=fmt(Date.now()-r.t0);row.appendChild(tm);}var pz=D.createElement('span');pz.className='arPause';pz.textContent='Paused';pz.hidden=!r.paused;row.appendChild(pz);if(r.canDelete===true){var xb=D.createElement('button');xb.type='button';xb.textContent='X';xb.title='Delete room';xb.setAttribute('aria-label','Delete room '+nm);xb.style.cssText='flex:none;margin-left:auto;font:inherit;font-weight:700;color:#fff;background:rgba(200,40,40,.55);border:1px solid rgba(255,255,255,.35);border-radius:4px;padding:0 5px;cursor:pointer';xb.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();if(!window.confirm('Do you want to delete that room?'))return;xb.disabled=true;fetch('/api/prerooms/'+encodeURIComponent(r.id)+'/delete',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:'{}'}).then(function(x){return x.json().then(function(j){if(!x.ok)throw new Error(j.error||x.status);rooms=rooms.filter(function(y){return y.id!==r.id;});draw(true);last=0;});}).catch(function(err){xb.disabled=false;alert('Could not delete: '+err.message);});});row.appendChild(xb);}if(r.badge){var g=D.createElement('span');g.className='arBadge';g.textContent=r.badge;row.appendChild(g);}box.appendChild(row);});});}
new MutationObserver(function(){draw(false);}).observe(D.documentElement,{childList:true,subtree:true});setInterval(function(){if(D.querySelector('.hrw .hrnewcol')){last=0;load();}},30000);draw(false);})();
